+        hr = pMFGSTBuffer->QueryInterface(IID_IMFMediaBuffer, (void **)&pBuffer);
+        if (FAILED(hr) || pBuffer == NULL)
+        {
+            delete pMFGSTBuffer;
+            return E_NOINTERFACE;
+        }
