+        if (SUCCEEDED(hr) && GST_BUFFER_PTS_IS_VALID(buf))
+            hr = (*ppSample)->SetSampleTime(GST_BUFFER_PTS(buf) / 100);
+
+        if (SUCCEEDED(hr) && GST_BUFFER_DURATION_IS_VALID(buf))
